SELECT * FROM (SELECT CASE WHEN unit_price >= 320 THEN 'high' WHEN unit_price >= 120 THEN 'mid' ELSE 'low' END unit_price_bucket, SUM(unit_price) total_unit_price FROM order_items WHERE quantity BETWEEN 6 AND 8 GROUP BY CASE WHEN unit_price >= 320 THEN 'high' WHEN unit_price >= 120 THEN 'mid' ELSE 'low' END) x WHERE total_unit_price > 600 ORDER BY total_unit_price DESC, unit_price_bucket LIMIT 5
